// 原Task和承诺先评估；每次真正采用仍核活跃策略/非玩家和作者来源，不能仅靠提案时权限。
#include "political_subordinate_appointment_director_world.hpp"
#include "world_bundle.hpp"
namespace hanmo::resident {namespace {
Outcome<StableId> policy_id(const WorldBundle& w,const StableId& actor){if(!w.catalog->director||!w.catalog->political_subordinate_appointment_intents||!w.catalog->political_subordinate_appointments||actor==w.common.state().metadata.player_actor_id)return {false,{},common_failure("PoliticalSubordinateIntentProfileRequired",actor).error};const auto* p=director_policy(w.director,*w.catalog->director,actor);if(!p||!p->political_career||!director_subject_active(w.director,actor)||std::find(p->templates.begin(),p->templates.end(),DirectorTemplate::political_career)==p->templates.end())return {false,{},common_failure("PoliticalSubordinateDirectorPolicyMismatch",actor).error};if(w.catalog->director->dynamic_subjects){const auto* r=w.director.registrations.find(actor);if(!r||r->obligations_only)return {false,{},common_failure("PoliticalSubordinateDirectorPolicyMismatch",actor).error};return {true,r->policy_id,{}};}return {true,actor,{}};}
Status guard(const WorldBundle& w,const StableId& actor,const AuthoredSubordinateAppointmentCommand& c){auto v=command_common_guard(w,actor,political_subordinate_appointment_command_kind(c.command));if(!v.ok)return v;auto id=policy_id(w,actor);if(!id.ok)return {false,{},id.error};return c.origin.actor_id==actor&&c.origin.director_policy_id==id.value?common_success():common_failure("PoliticalSubordinateAuthoredOriginMismatch",actor);}
class Read final:public PoliticalSubordinateAppointmentDirectorRead {
 const PoliticalSubordinateAppointmentContext& rules_;PoliticalNavigationRead navigation_;
public:
 Read(const PoliticalSubordinateAppointmentContext& x,const PoliticalNavigationRead& n):rules_(x),navigation_(n){}
 Outcome<PoliticalSubordinateAppointmentChoice> choose(const StableId& actor,const StableId& policy,Integer budget)const override{return propose_political_subordinate_appointment(rules_,navigation_,actor,policy,budget);}
 Outcome<std::shared_ptr<const CommandPayload>> command(const AuthoredSubordinateAppointmentCommand& c)const override{return {true,std::make_shared<const CommandPayload>(CommandPayload{political_subordinate_appointment_command_kind(c.command),c}),{}};}
};
}
Outcome<std::optional<DecisionProposal>> propose_political_subordinate_appointment_world(const WorldBundle& w,const KnownSubjectView& known,const DirectorPolicy& policy,const DecisionProposal& base){auto id=policy_id(w,known.actor_id);if(!id.ok)return id.error.kind==ErrorKind::rule?Outcome<std::optional<DecisionProposal>>{true,std::nullopt,{}}:Outcome<std::optional<DecisionProposal>>{false,{},id.error};if(!w.catalog->travel)return {false,{},common_failure("PoliticalSubordinateTravelProfileRequired").error};auto holder=PoliticalSubordinateAppointmentWorldAccess::create(w);if(!holder.ok)return {false,{},holder.error};Read read(holder.value->context(),{w.travel,*w.catalog->travel,w.services});return propose_director_subordinate_appointment(w.common,known,policy,id.value,read,base,w.catalog->director->candidates_per_subject);}
Outcome<PoliticalSubordinateAppointmentQuote> prepare_authored_subordinate_appointment_world(const WorldBundle& w,const StableId& actor,const AuthoredSubordinateAppointmentCommand& c){auto v=guard(w,actor,c);if(!v.ok)return {false,{},v.error};auto holder=PoliticalSubordinateAppointmentWorldAccess::create(w);if(!holder.ok)return {false,{},holder.error};auto rules=holder.value->context();rules.authored=&c.origin;return preview_political_subordinate_appointment(rules,actor,c.command);}
Outcome<PoliticsEffects> commit_authored_subordinate_appointment_world(WorldBundle& w,const StableId& actor,const AuthoredSubordinateAppointmentCommand& c,const PoliticalSubordinateAppointmentQuote& q){auto v=guard(w,actor,c);if(!v.ok)return {false,{},v.error};auto holder=PoliticalSubordinateAppointmentWorldAccess::create(w);if(!holder.ok)return {false,{},holder.error};auto rules=holder.value->context();rules.authored=&c.origin;return apply_political_subordinate_appointment_business_in_candidate(w.common,w.organization,*w.political_subordinate_appointments,rules,actor,c.command,q);}
Status validate_political_subordinate_appointment_director_world(const WorldBundle& w){if(!w.catalog->director)return w.catalog->political_subordinate_appointment_intents?common_failure("PoliticalSubordinateIntentProfileRequired"):common_success();if(!w.catalog->political_subordinate_appointment_intents)return validate_political_subordinate_appointment_director(*w.catalog->director,w.director,nullptr);auto holder=PoliticalSubordinateAppointmentWorldAccess::create(w);return holder.ok?validate_political_subordinate_appointment_director(*w.catalog->director,w.director,&holder.value->context()):Status{false,{},holder.error};}
}
